"""Value semantics and expression evaluation for minisql.

This module is deliberately independent of parsing and table loading: it works
on :mod:`minisql.ast` nodes and plain Python values.  ``None`` represents SQL
NULL everywhere.

The engine calls :func:`validate` once on every expression it accepts, then
:func:`evaluate` once per row (or per group).  Aggregates are computed with
:func:`compute_aggregate` and their results are placed in an
:class:`EvalContext` keyed by ``id()`` of the aggregate node.
"""

import math
import re
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, localcontext
from functools import lru_cache

from . import ast
from .errors import QueryError


AGGREGATES = frozenset({"COUNT", "SUM", "AVG", "MIN", "MAX"})

# name -> (minimum argument count, maximum argument count or None)
_SCALAR_ARITY = {
    "LOWER": (1, 1),
    "UPPER": (1, 1),
    "LENGTH": (1, 1),
    "ABS": (1, 1),
    "ROUND": (1, 2),
    "COALESCE": (1, None),
}

_COMPARISON_OPS = frozenset({"=", "!=", "<>", "<", "<=", ">", ">="})


class EvalContext:
    """Values visible while evaluating one expression.

    ``columns`` maps lower-case column names to row values.  ``aggregates``
    maps ``id(FuncCall node)`` to the already-computed value of that aggregate.
    """

    def __init__(self, columns=None, aggregates=None):
        self.columns = columns or {}
        self.aggregates = aggregates or {}


# ---------------------------------------------------------------------------
# Small value helpers
# ---------------------------------------------------------------------------


def _type_label(value):
    """Return a human-readable type name for error messages."""
    if value is None:
        return "NULL"
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, int):
        return "integer"
    if isinstance(value, float):
        return "float"
    if isinstance(value, str):
        return "string"
    return type(value).__name__


def _is_number(value):
    """True for int/float, but deliberately false for bool."""
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _require_number(value, name):
    if not _is_number(value):
        raise QueryError(
            "%s() requires a numeric argument, got %s"
            % (name, _type_label(value))
        )
    return value


def _require_string(value, name):
    if not isinstance(value, str):
        raise QueryError(
            "%s() requires a string argument, got %s"
            % (name, _type_label(value))
        )
    return value


def _check_arity(name, count, minimum, maximum):
    """Raise :class:`QueryError` unless ``minimum <= count <= maximum``."""
    if count < minimum or (maximum is not None and count > maximum):
        if maximum is None:
            expected = "at least %d" % minimum
        elif minimum == maximum:
            expected = "exactly %d" % minimum
        else:
            expected = "between %d and %d" % (minimum, maximum)
        raise QueryError(
            "%s() expects %s argument%s, got %d"
            % (name, expected, "" if expected.endswith("1") else "s", count)
        )


# ---------------------------------------------------------------------------
# Public value helpers
# ---------------------------------------------------------------------------


def truth(value):
    """Return the SQL truth value of ``value``: True, False, or None.

    Only actual booleans are condition values; anything else (for example the
    integer in ``WHERE 1``) is an error.
    """
    if value is True:
        return True
    if value is False:
        return False
    if value is None:
        return None
    raise QueryError(
        "condition must be TRUE, FALSE, or NULL, got %s" % _type_label(value)
    )


def compare_values(a, b):
    """Compare two non-NULL values, returning -1, 0, or 1.

    Numbers (int/float) compare numerically, strings by code point, and
    booleans with booleans.  Mixing those categories is an error.  NULLs are
    the caller's responsibility.
    """
    if a is None or b is None:
        raise QueryError("cannot compare NULL values")

    if _is_number(a) and _is_number(b):
        if a < b:
            return -1
        if a > b:
            return 1
        return 0

    if isinstance(a, str) and isinstance(b, str):
        if a < b:
            return -1
        if a > b:
            return 1
        return 0

    if isinstance(a, bool) and isinstance(b, bool):
        if a == b:
            return 0
        return -1 if a is False else 1

    raise QueryError(
        "cannot compare %s with %s" % (_type_label(a), _type_label(b))
    )


def to_concat_text(value):
    """Return the text used by ``||`` for a non-NULL value."""
    if value is None:
        raise QueryError("cannot convert NULL to text")
    if isinstance(value, bool):
        return "true" if value else "false"
    return str(value)


@lru_cache(maxsize=256)
def _like_regex(pattern):
    """Translate a LIKE pattern into an equivalent regular expression."""
    parts = []
    for char in pattern:
        if char == "%":
            parts.append(".*")
        elif char == "_":
            parts.append(".")
        else:
            parts.append(re.escape(char))
    return "".join(parts)


def like(value, pattern):
    """Whole-string, case-sensitive LIKE matching for non-NULL strings."""
    if not isinstance(value, str) or not isinstance(pattern, str):
        raise QueryError(
            "LIKE requires string operands, got %s and %s"
            % (_type_label(value), _type_label(pattern))
        )
    return re.fullmatch(_like_regex(pattern), value, re.DOTALL) is not None


# ---------------------------------------------------------------------------
# Aggregate classification
# ---------------------------------------------------------------------------


def is_aggregate(node):
    """True if ``node`` is a call to COUNT, SUM, AVG, MIN, or MAX."""
    return isinstance(node, ast.FuncCall) and node.name in AGGREGATES


def has_aggregate(expr):
    """True if ``expr`` or any descendant is an aggregate call."""
    return any(is_aggregate(node) for node in ast.walk(expr))


def iter_aggregates(expr):
    """Return every aggregate ``FuncCall`` inside ``expr``, outermost first."""
    return [node for node in ast.walk(expr) if is_aggregate(node)]


# ---------------------------------------------------------------------------
# Validation
# ---------------------------------------------------------------------------


def _nested_aggregate_error(outer, inner):
    return QueryError(
        "aggregate functions cannot be nested: %s() inside %s()"
        % (inner.name, outer.name)
    )


def _validate_node(node, allow_aggregates):
    if isinstance(node, ast.Star):
        raise QueryError("'*' is only allowed as COUNT(*)")

    if isinstance(node, ast.FuncCall):
        name = node.name
        args = node.args

        if name in AGGREGATES:
            if not allow_aggregates:
                raise QueryError(
                    "aggregate function %s() is not allowed here" % name
                )
            if len(args) != 1:
                raise QueryError(
                    "aggregate function %s() expects exactly 1 argument, got %d"
                    % (name, len(args))
                )
            arg = args[0]
            if isinstance(arg, ast.Star):
                if name != "COUNT":
                    raise QueryError(
                        "'*' is only allowed as COUNT(*), not %s(*)" % name
                    )
                return
            if has_aggregate(arg):
                inner = next(
                    item for item in ast.walk(arg) if is_aggregate(item)
                )
                raise _nested_aggregate_error(node, inner)
            # The argument of an aggregate cannot itself contain aggregates.
            _validate_node(arg, False)
            return

        spec = _SCALAR_ARITY.get(name)
        if spec is None:
            raise QueryError('unknown function "%s"' % name)
        _check_arity(name, len(args), spec[0], spec[1])
        for arg in args:
            _validate_node(arg, allow_aggregates)
        return

    for child in ast.child_exprs(node):
        _validate_node(child, allow_aggregates)


def validate(expr, allow_aggregates=True):
    """Check an expression for unknown functions, arity, and ``*`` placement.

    Aggregates nested inside aggregates are always rejected.  When
    ``allow_aggregates`` is false (for example in ``WHERE``), any aggregate is
    rejected as well.
    """
    _validate_node(expr, allow_aggregates)


# ---------------------------------------------------------------------------
# Evaluation
# ---------------------------------------------------------------------------


def _lookup_column(node, ctx):
    key = node.name.lower()
    try:
        return ctx.columns[key]
    except KeyError:
        raise QueryError('unknown column "%s"' % node.name) from None


def _and3(left, right):
    """Three-valued AND of already-canonical truth values."""
    if left is False or right is False:
        return False
    if left is None or right is None:
        return None
    return True


def _or3(left, right):
    """Three-valued OR of already-canonical truth values."""
    if left is True or right is True:
        return True
    if left is None or right is None:
        return None
    return False


def _negate3(value):
    return None if value is None else not value


def _comparison_result(op, left, right):
    if left is None or right is None:
        return None
    order = compare_values(left, right)
    if op == "=":
        return order == 0
    if op in ("!=", "<>"):
        return order != 0
    if op == "<":
        return order < 0
    if op == "<=":
        return order <= 0
    if op == ">":
        return order > 0
    return order >= 0  # ">="


def _eval_unary(node, ctx):
    value = evaluate(node.operand, ctx)
    if node.op == "NOT":
        return _negate3(truth(value))
    if node.op == "-":
        if value is None:
            return None
        if not _is_number(value):
            raise QueryError(
                "unary '-' requires a number, got %s" % _type_label(value)
            )
        return -value
    raise QueryError('unknown unary operator "%s"' % node.op)


def _eval_arithmetic(op, left, right):
    if left is None or right is None:
        return None
    for value in (left, right):
        if not _is_number(value):
            raise QueryError(
                "operator '%s' requires numeric operands, got %s"
                % (op, _type_label(value))
            )

    if op == "/":
        if right == 0:
            return None
        try:
            return left / right
        except OverflowError:
            raise QueryError(
                "arithmetic overflow in operator '/'"
            ) from None
    try:
        if op == "+":
            return left + right
        if op == "-":
            return left - right
        return left * right  # "*"
    except OverflowError:
        raise QueryError(
            "arithmetic overflow in operator '%s'" % op
        ) from None


def _eval_binary(node, ctx):
    op = node.op

    if op == "AND":
        return _and3(
            truth(evaluate(node.left, ctx)),
            truth(evaluate(node.right, ctx)),
        )
    if op == "OR":
        return _or3(
            truth(evaluate(node.left, ctx)),
            truth(evaluate(node.right, ctx)),
        )
    if op in _COMPARISON_OPS:
        return _comparison_result(
            op, evaluate(node.left, ctx), evaluate(node.right, ctx)
        )
    if op in ("+", "-", "*", "/"):
        return _eval_arithmetic(
            op, evaluate(node.left, ctx), evaluate(node.right, ctx)
        )
    if op == "||":
        left = evaluate(node.left, ctx)
        right = evaluate(node.right, ctx)
        if left is None or right is None:
            return None
        return to_concat_text(left) + to_concat_text(right)

    raise QueryError('unknown operator "%s"' % op)


def _eval_in(node, ctx):
    value = evaluate(node.operand, ctx)
    items = [evaluate(item, ctx) for item in node.items]

    if value is None:
        result = None
    else:
        result = False
        saw_null = False
        for item in items:
            if item is None:
                saw_null = True
                continue
            if compare_values(value, item) == 0:
                result = True
        if result is False and saw_null:
            result = None

    if node.negated:
        result = _negate3(result)
    return result


def _eval_between(node, ctx):
    value = evaluate(node.operand, ctx)
    low = evaluate(node.low, ctx)
    high = evaluate(node.high, ctx)

    lower_ok = (
        None if value is None or low is None
        else compare_values(low, value) <= 0
    )
    upper_ok = (
        None if value is None or high is None
        else compare_values(value, high) <= 0
    )
    result = _and3(lower_ok, upper_ok)
    if node.negated:
        result = _negate3(result)
    return result


def _eval_like(node, ctx):
    value = evaluate(node.operand, ctx)
    pattern = evaluate(node.pattern, ctx)
    if value is None or pattern is None:
        return None
    result = like(value, pattern)
    return _negate3(result) if node.negated else result


def _round_half_away_from_zero(value, digits):
    """Round ``value`` to ``digits`` decimal places, halves away from zero.

    Decimal is used so that decimal input such as ``1.005`` rounds the way a
    human expects instead of being distorted by binary floating point.
    """
    try:
        decimal_value = Decimal(str(value))
    except (InvalidOperation, ValueError):
        raise QueryError("ROUND() cannot round %r" % (value,)) from None
    if not decimal_value.is_finite():
        raise QueryError("ROUND() cannot round %r" % (value,))

    quantum = Decimal(1).scaleb(-digits)
    with localcontext() as context:
        context.prec = max(28, decimal_value.adjusted() + digits + 10)
        try:
            return decimal_value.quantize(quantum, rounding=ROUND_HALF_UP)
        except InvalidOperation:
            raise QueryError("ROUND() cannot round %r" % (value,)) from None


def _eval_scalar(node, ctx):
    name = node.name
    args = node.args

    spec = _SCALAR_ARITY.get(name)
    if spec is None:
        raise QueryError('unknown function "%s"' % name)

    if name == "COALESCE":
        _check_arity(name, len(args), spec[0], spec[1])
        for arg in args:
            value = evaluate(arg, ctx)
            if value is not None:
                return value
        return None

    _check_arity(name, len(args), spec[0], spec[1])
    values = [evaluate(arg, ctx) for arg in args]
    if any(value is None for value in values):
        return None

    if name == "LOWER":
        return _require_string(values[0], name).lower()
    if name == "UPPER":
        return _require_string(values[0], name).upper()
    if name == "LENGTH":
        return len(_require_string(values[0], name))
    if name == "ABS":
        return abs(_require_number(values[0], name))
    if name == "ROUND":
        number = _require_number(values[0], name)
        if len(values) == 1:
            return int(_round_half_away_from_zero(number, 0))
        digits = values[1]
        if isinstance(digits, bool) or not isinstance(digits, int):
            raise QueryError(
                "ROUND() second argument must be an integer, got %s"
                % _type_label(digits)
            )
        if digits < 0:
            raise QueryError(
                "ROUND() second argument must be non-negative, got %d" % digits
            )
        return float(_round_half_away_from_zero(number, digits))

    # Unreachable while _SCALAR_ARITY and this function stay in sync.
    raise QueryError('unknown function "%s"' % name)


def _eval_func(node, ctx):
    if is_aggregate(node):
        try:
            return ctx.aggregates[id(node)]
        except KeyError:
            raise QueryError(
                "internal error: no value for aggregate %s()" % node.name
            ) from None
    return _eval_scalar(node, ctx)


def evaluate(expr, ctx):
    """Evaluate ``expr`` against ``ctx`` and return a Python value (or None)."""
    if isinstance(expr, ast.Literal):
        return expr.value
    if isinstance(expr, ast.ColumnRef):
        return _lookup_column(expr, ctx)
    if isinstance(expr, ast.Star):
        raise QueryError("'*' is only allowed as COUNT(*)")
    if isinstance(expr, ast.UnaryOp):
        return _eval_unary(expr, ctx)
    if isinstance(expr, ast.BinaryOp):
        return _eval_binary(expr, ctx)
    if isinstance(expr, ast.IsNull):
        value = evaluate(expr.operand, ctx)
        return (value is None) if not expr.negated else (value is not None)
    if isinstance(expr, ast.InList):
        return _eval_in(expr, ctx)
    if isinstance(expr, ast.Between):
        return _eval_between(expr, ctx)
    if isinstance(expr, ast.Like):
        return _eval_like(expr, ctx)
    if isinstance(expr, ast.FuncCall):
        return _eval_func(expr, ctx)

    raise QueryError(
        "cannot evaluate %s expression" % type(expr).__name__
    )


# ---------------------------------------------------------------------------
# Aggregates
# ---------------------------------------------------------------------------


def compute_aggregate(node, rows):
    """Compute aggregate ``node`` over ``rows``.

    Each row is a dict mapping lower-case column names to values.  ``rows``
    may be empty: COUNT yields 0 and the other aggregates yield NULL.
    """
    if not is_aggregate(node):
        raise QueryError(
            "compute_aggregate() requires an aggregate function call"
        )

    # Checks arity, nested aggregates, and Star placement.
    validate(node)

    name = node.name
    args = node.args

    if name == "COUNT" and isinstance(args[0], ast.Star):
        return len(rows)

    arg = args[0]
    context = EvalContext
    values = []
    for row in rows:
        value = evaluate(arg, context(columns=row))
        if value is not None:
            values.append(value)

    if name == "COUNT":
        return len(values)

    if not values:
        return None

    if name == "SUM":
        total = 0
        has_float = False
        for value in values:
            _require_number(value, "SUM")
            if isinstance(value, float):
                has_float = True
            total += value
        return float(total) if has_float else total

    if name == "AVG":
        total = 0
        for value in values:
            _require_number(value, "AVG")
            total += value
        return float(total) / len(values)

    # MIN and MAX.
    best = None
    for value in values:
        if best is None:
            best = value
            continue
        order = compare_values(value, best)
        if (name == "MIN" and order < 0) or (name == "MAX" and order > 0):
            best = value
    return best


# ---------------------------------------------------------------------------
# GROUP BY checking
# ---------------------------------------------------------------------------


def _contains_column_ref(expr):
    return any(isinstance(node, ast.ColumnRef) for node in ast.walk(expr))


def _grouped_error(expr):
    if isinstance(expr, ast.ColumnRef):
        return QueryError(
            'column "%s" must appear in GROUP BY or be used in an aggregate '
            "function" % expr.name
        )
    text = getattr(expr, "text", "") or type(expr).__name__
    return QueryError(
        'expression "%s" must appear in GROUP BY or be used in an aggregate '
        "function" % text
    )


def _check_grouped(expr, group_keys):
    if is_aggregate(expr):
        return
    if ast.expr_key(expr) in group_keys:
        return
    if not has_aggregate(expr):
        if _contains_column_ref(expr):
            raise _grouped_error(expr)
        return
    for child in ast.child_exprs(expr):
        _check_grouped(child, group_keys)


def check_grouped(expr, group_keys):
    """Enforce SPEC.md's rule for columns in a grouped query.

    Every subexpression that contains a column reference but no aggregate must
    be structurally equal to one of the ``GROUP BY`` expressions (whose
    ``ast.expr_key`` values are in ``group_keys``); constants are always fine.
    """
    keys = set(group_keys or ())
    _check_grouped(expr, keys)

